mapper.select:
SELECT id, oper_user_id, oper_username, oper_nickname, module_name, oper_title,
       oper_type, request_url, request_method, ip_address, browser, os,
       cost_time, status, create_time
FROM sys_oper_log

    delete_flag = 0

        AND (
            oper_username LIKE CONCAT('%', #{keyword}, '%')
            OR oper_nickname LIKE CONCAT('%', #{keyword}, '%')
            OR oper_title LIKE CONCAT('%', #{keyword}, '%')
        )


        AND module_name LIKE CONCAT('%', #{moduleName}, '%')

    AND oper_type = #{operType}
    AND status = #{status}
    AND create_time >= #{beginTime}
    AND create_time <= #{endTime}

ORDER BY create_time DESC, id DESC

mapper.delete:
DELETE FROM sys_oper_log
WHERE id IN
#{id}
